/**
 * Paths swamp vaults in a resource schema: fields carrying
 * .meta({ sensitive: true }) on the field or on an optional, nullable or
 * default wrapper around it, found by walking plain object shapes only (swamp
 * does not enter arrays or unions, or see through readonly or catch).
 */
function swampSensitivePaths(schema: unknown, prefix = ""): string[] {
  // deno-lint-ignore no-explicit-any
  const inner = (s: any): any =>
    ["optional", "nullable", "default"].includes(s?._zod?.def?.type)
      ? s._zod.def.innerType
      : undefined;
  // deno-lint-ignore no-explicit-any
  const unwrap = (s: any): any => {
    while (inner(s)) s = inner(s);
    return s;
  };
  // deno-lint-ignore no-explicit-any
  const isMarked = (s: any): boolean => {
    for (let cur = s; cur; cur = inner(cur)) {
      if (cur.meta?.()?.sensitive === true) return true;
    }
    return false;
  };
  const obj = unwrap(schema);
  if (obj?._zod?.def?.type !== "object") return [];
  const out: string[] = [];
  for (const [key, field] of Object.entries(obj._zod.def.shape)) {
    const path = prefix ? prefix + "." + key : key;
    if (isMarked(field)) out.push(path);
    out.push(...swampSensitivePaths(field, path));
  }
  return out.sort();
}

Deno.test({
  name:
    "registrar model: transfer_domain marks auth_code sensitive and never writes it",
  sanitizeResources: false,
  fn: async () => {
    const { url, server, requests } = startMockServer({
      "POST /1010/registrar/domains/test-id-123/transfers": {
        "status": 200,
        "body": {
          "data": {
            "id": 1,
            "domain_id": 1,
            "registrant_id": 1,
            "state": "cancelled",
            "auto_renew": true,
            "whois_privacy": true,
            "trustee": true,
            "status_description": "test-value",
            "created_at": "2010-01-01T01:00:00Z",
            "updated_at": "2010-01-01T01:00:00Z",
          },
        },
      },
    });
    const uninstall = installFetchMock(url);

    try {
      const { context, getWrittenResources } = newContext();
      const plaintext = { "auth_code": "plaintext-secret-auth_code" };
      const marked = swampSensitivePaths(
        model.methods.transfer_domain.arguments,
      );
      assertEquals(marked, ["auth_code"]);

      await run("transfer_domain", {
        "domain": "test-id-123",
        "registrant_id": 1,
        "auth_code": "plaintext-secret-auth_code",
        "whois_privacy": true,
        "auto_renew": true,
        "trustee": true,
        "extended_attributes": {},
        "premium_price": "test-value",
      }, context);

      // The secret reaches the API...
      const sent = JSON.stringify(requests[0].body);
      for (const value of Object.values(plaintext)) {
        assertEquals(sent.includes(value), true);
      }
      // ...and nothing swamp stores holds it.
      const stored = JSON.stringify(getWrittenResources());
      for (const value of Object.values(plaintext)) {
        assertEquals(stored.includes(value), false);
      }
    } finally {
      uninstall();
      await server.shutdown();
    }
  },
});
